INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 10, 'theory', 'DNS: How a Name Becomes an Address');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 0, 'What does a recursive resolver do when it receives a client''s question?', '["It answers only from its own records", "It passes the question to another server''s client", "It walks the chain: root, TLD, authoritative server, and returns a ready answer to the client", "It redirects the client to a root server"]', 2, 'The resolver does all the iterative work for the client and caches what it receives.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 1, 'What does an NXDOMAIN reply mean?', '["There is no such name", "The server is unavailable", "The request was rejected", "There is an answer, but it is empty"]', 0, 'NXDOMAIN is a final "no such name" answer; an unreachable server gives SERVFAIL or silence.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 2, 'What does a CNAME record do?', '["Links a name to an IPv6 address", "Declares a name to be an alias of another name", "Points to a mail server", "Signs the zone"]', 1, 'When a resolver meets a CNAME, it continues the search, now for the new name.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 3, 'What is the TTL of a DNS record for?', '["It limits the number of requests", "It sets the server''s priority", "It sets how long the record may be kept in the cache", "It determines the record type"]', 2, 'When the TTL expires, the resolver must request the record again.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 10, 4, 'For one user the site opens at the old address, while everyone else gets the new one. What should you check first?', '["The entry in the hosts file on their computer and their resolver''s cache", "The server''s power", "The MTU size", "The HTTP version"]', 0, 'The hosts file beats a DNS answer, and a resolver may keep the old answer until the TTL ends.');
